package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import com.lianxibu.site.service.jobs.ReportInputSnapshotService.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
/** Pure fictional count/source inputs only. This mapper cannot issue a native permission. */
class EntityHeatSupplementCandidateTest {
 final EntityHeatReportCandidateTest h=new EntityHeatReportCandidateTest();final Instant cutoff=h.cutoff.plusSeconds(30).plusNanos(1000);
 ReportInputSnapshotService.FrozenInput freeze(List<EntityHeatReportCandidate.Value> values){var candidates=new ArrayList<Candidate>();candidates.add(h.daily());values.forEach(v->candidates.add(v.candidate()));var ids=values.stream().map(v->v.dependency().id()).distinct().toList();var command=new Prepare("report:daily:"+h.day,2,Stage.DAILY_REPORT,h.day,null,List.of(),List.of(),List.of(),true,"d".repeat(64));return new ReportInputSnapshotService((c,t)->new SourceProof(t,h.day,h.day.plusDays(1),true,candidates,List.of(),List.of(),ids)).freeze(command,cutoff);}
 @Test void ExplicitMicrosecondMapperPreservesFullOriginalBodyAndExactNewCountCutoff(){var leaf=h.leaf("fictional-entity",true,false);var value=EntityHeatReportCandidate.createSupplement(h.count(leaf.entityId(),19),leaf,cutoff,true);assertEquals(cutoff,value.candidate().countCutoff());assertEquals(19,value.candidate().metadata().occurrenceCount());assertEquals(CanonicalJson.parse(leaf.bodyJson()),CanonicalJson.parse(value.candidate().evidence().bodyJson()).get("source_member").get("body"));assertEquals(value,EntityHeatReportCandidate.createSupplement(h.count(leaf.entityId(),19),leaf,cutoff,true));var frozen=freeze(List.of(value));assertTrue(frozen.hasContent());assertEquals(cutoff,WireValues.utcMicroseconds(CanonicalJson.parse(frozen.snapshotJson()).get("cutoff")));assertEquals(2,CanonicalJson.parse(frozen.snapshotJson()).get("members").size());}
 @Test void InitialMapperStillRequiresFiveClockAndOldCountCannotPretendToBeNewCutoff(){var leaf=h.leaf("fictional-entity",true,false);assertThrows(RuntimeException.class,()->EntityHeatReportCandidate.create(h.count(leaf.entityId(),19),leaf,cutoff,true));var old=EntityHeatReportCandidate.create(h.count(leaf.entityId(),1),leaf,h.cutoff,true);assertThrows(ReportInputSnapshotService.ProofUnavailable.class,()->freeze(List.of(old)));var current=EntityHeatReportCandidate.createSupplement(h.count(leaf.entityId(),19),leaf,cutoff,true);assertNotEquals(old.candidate().evidence().bodyHash(),current.candidate().evidence().bodyHash());assertEquals(1,old.candidate().metadata().occurrenceCount());}
 @Test void FullNewCutoffRankingRecomputesAfterInvalidBodyInsteadOfKeepingTopFive(){var values=new ArrayList<EntityHeatReportCandidate.Value>();for(int n=0;n<7;n++){String id="fictional-entity-"+n;values.add(EntityHeatReportCandidate.createSupplement(h.count(id,n==6?99:8),h.leaf(id,n!=6,false),cutoff,true));}var frozen=freeze(values);var profile=CanonicalJson.parse(frozen.snapshotJson()).get(com.lianxibu.site.service.content.ReportInputProfile.FIELD);var included=profile.get("members").valueStream().filter(v->v.get("group").asText().equals("historical_heat")&&v.get("included").booleanValue()).toList();assertEquals(5,included.size());assertEquals(Set.of("fictional-entity-0","fictional-entity-1","fictional-entity-2","fictional-entity-3","fictional-entity-4"),included.stream().map(v->v.get("resource_ref").get("id").asText()).collect(java.util.stream.Collectors.toSet()));}
 @Test void ExplicitMappingRejectsNonMicrosecondWrongEntityUnknownAndLateOriginalFacts(){var leaf=h.leaf("fictional-entity",true,false);assertThrows(RuntimeException.class,()->EntityHeatReportCandidate.createSupplement(h.count(leaf.entityId(),1),leaf,cutoff.plusNanos(1),true));assertThrows(RuntimeException.class,()->EntityHeatReportCandidate.createSupplement(h.count("fictional-alien",1),leaf,cutoff,true));assertThrows(RuntimeException.class,()->EntityHeatReportCandidate.createSupplement(h.count(leaf.entityId(),1),leaf,h.cutoff.minusSeconds(3),true));var unknown=new EntityHeatCutoffProofService.Count(new EntityHeatSnapshot(leaf.entityId(),"news_tech",3,null,null,null,null,null,true),"a".repeat(64),"b".repeat(64),h.cutoff);assertThrows(RuntimeException.class,()->EntityHeatReportCandidate.createSupplement(unknown,leaf,cutoff,true));}
}
